package com.bank.qa.cidebug;

import java.util.*;
import java.util.logging.*;

public class CiDebugDemo {
    private static final Logger log = Logger.getLogger(CiDebugDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new CiLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Local (passes) vs CI (fails) snapshots.
        EnvSnapshot local = new EnvSnapshot("LOCAL", Map.of(
            "node", "20.11", "playwrightVersion", "1.47", "os", "macOS",
            "timeZone", "Asia/Kolkata", "BASE_URL", "http://localhost:3000",
            "BANK_PASS", "set", "networkAccess", "full", "cpuCores", "10"));

        EnvSnapshot ci = new EnvSnapshot("CI", Map.of(
            "node", "20.11", "playwrightVersion", "1.47", "os", "Linux",
            "timeZone", "UTC", "BASE_URL", "https://staging.nationalbank.example",
            "BANK_PASS", "<missing>", "networkAccess", "restricted", "cpuCores", "2"));

        log.info("=== Compare environments to find the REAL difference ===");
        List<String> diffs = new EnvDiffer().diff(local, ci);
        log.info("Differences found: " + diffs);
        log.info("Fix the environmental causes (inject BANK_PASS, pin timeZone, "
            + "allow network, size workers), NOT the test logic.");
        log.info("Reproduce locally by matching CI: run in a Linux container with "
            + "UTC, same env vars -> see the failure -> fix the cause.");
    }
}

